contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public payable {
        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        c.SetMinSum(_val); if (__ESBMC_reverted()) return;
        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        assert(afterUnlockTime == beforeUnlockTime && afterBalance == beforeBalance);
    }
}

