pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _val) internal {
        uint256 beforeUnlockTime;
        uint256 beforeBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeUnlockTime = __r0; beforeBalance = __r1; } catch { return; }
        try c.SetMinSum(_val) {} catch { return; }
        uint256 afterUnlockTime;
        uint256 afterBalance;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterUnlockTime = __r0; afterBalance = __r1; } catch { return; }
        assertTrue(afterUnlockTime == beforeUnlockTime && afterBalance == beforeBalance);
    }

    function testFuzz_run(uint256 _val) public {
        _run(_val);
    }

    receive() external payable {}
}
